var n=`1201-baleadas`;var i=`world-1201`;var t=`HN`;var o=`central-america-caribbean`;var s=4;var r=601;var d={en:`Baleadas`,ua:`Балеадас`};var l={en:`Baleadas is a dish from Honduras featuring all-purpose flour, kidney beans, queso fresco, sour cream. This home-sized recipe records each ingredient at the step where it is used. Refried red beans are made at home from cooked kidney beans; authentic baleada beans are often blended more finely.`,ua:`Балеадас, страва кухні країни Гондурас з такими основними складниками: пшеничне борошно універсальне, червона квасоля кідні, кесо фреско, сметана. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Червону квасолю для начинки розминають удома; традиційна квасолева паста для балеадас часто дрібніша.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,420,`g`],[`water`,230,`ml`],[`table-salt`,7,`g`],[`canola-oil`,30,`ml`]]},{en:`Soak the dried beans in ample clean cold water for about 480 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 480 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:480,i:[[`kidney-beans`,320,`g`],[`water`,950,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 75 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 75 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:75,i:[[`water`,900,`ml`]]},{en:`Mash the fully cooked beans with a little of their cooking liquid into a thick spread, then spoon onto the warm tortillas.`,ua:`Розімніть повністю приготовану квасолю із невеликою кількістю рідини на густу пасту для коржів.`,t:[`mashing`],m:7,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 14 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 14 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:14,i:[[`canola-oil`,25,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`queso-fresco`,240,`g`],[`sour-cream`,160,`g`],[`avocado`,2,`pcs`]]}];var m={slug:n,id:i,country:`HN`,region:o,servings:4,minutes:601,title:d,text:l,steps:u};export{t as country,m as default,i as id,r as minutes,o as region,s as servings,n as slug,u as steps,l as text,d as title};